import numpy as np
import pandas as pd

def task_func(df, letter):
    data = pd.DataFrame(df)

    if "Word" not in data.columns:
        return {"mean": np.nan, "median": np.nan, "mode": np.nan}

    words = data["Word"]

    mask = words.apply(lambda x: isinstance(x, str) and x.startswith(letter))
    filtered_words = words[mask]

    if filtered_words.empty:
        return {"mean": np.nan, "median": np.nan, "mode": np.nan}

    lengths = filtered_words.map(len)

    mean_val = float(lengths.mean())
    median_val = float(lengths.median())
    mode_series = lengths.mode()
    mode_val = float(mode_series.iloc[0]) if not mode_series.empty else np.nan

    return {"mean": mean_val, "median": median_val, "mode": mode_val}
